import { strict as assert } from "node:assert";
import { createContext, runInContext } from "node:vm";
import { readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";

if (process.env.HF_UI044_F3_PROBE !== "1") throw new Error("EXPLICIT_SYNTHETIC_PROBE_REQUIRED");
const revision = process.env.HF_UI044_WAIT_REVISION;
if (!["before", "after"].includes(revision)) throw new Error("EXPLICIT_BEFORE_OR_AFTER_REQUIRED");
const module = await import("../../../wt-p03/tests/e2e/support/frontend-mission-evidence.ts");
const { waitForMissionRender } = module.default ?? module;
const cases = ["pauses-after-snapshot", "removed-after-snapshot", "replaced-after-snapshot", "natural-finish", "finite-keeps-running", "paused-at-entry", "infinite-at-entry", "animation-during-final-barrier", "late-focus"];
const results = [];

for (const kind of cases) {
  let frame = 0;
  let nextId = 0;
  let frames = [];
  let tasks = [];
  let resolved = false;
  let resolvedAt = null;
  let samples = 0;
  let finishedReads = 0;
  let channels = 0;
  let messages = 0;
  let pendingFocus = false;
  let focusReveals = 0;
  let pendingAtReadiness = null;
  const trace = [];
  const animation = (state = "running", endTime = 300) => {
    let finish;
    const promise = new Promise(resolve => { finish = resolve; });
    return {
      playState: state, effect: { getComputedTiming: () => ({ endTime }) },
      get finished() { finishedReads++; return promise; },
      finish() { this.playState = "finished"; finish(); },
    };
  };
  const first = animation(kind === "paused-at-entry" ? "paused" : "running", kind === "infinite-at-entry" ? Infinity : 300);
  const replacement = animation();
  let animations = ["animation-during-final-barrier", "late-focus"].includes(kind) ? [] : [first];
  const context = createContext({
    __name: (fn, name) => Object.defineProperty(fn, "name", { value: name, configurable: true }),
    document: { getAnimations: () => { samples++; trace.push({ frame, event: "sample", states: animations.map(a => a.playState) }); return animations; } },
    requestAnimationFrame: callback => { frames.push(callback); return ++nextId; },
    MessageChannel: class {
      constructor() {
        channels++;
        this.port1 = { onmessage: null, close() {} };
        this.port2 = { close() {}, postMessage: () => tasks.push(() => { messages++; this.port1.onmessage(); }) };
      }
    },
  });
  runInContext(`(${waitForMissionRender.toString()})()`, context).then(() => {
    resolved = true; resolvedAt = frame; pendingAtReadiness = pendingFocus;
    trace.push({ frame, event: "resolved" });
  });
  for (frame = 1; frame <= 12; frame++) {
    if (frame === 1 && kind === "pauses-after-snapshot") first.playState = "paused";
    if (frame === 1 && kind === "removed-after-snapshot") animations = [];
    if (frame === 1 && kind === "replaced-after-snapshot") { first.playState = "paused"; animations = [replacement]; }
    if (frame === 3 && kind === "natural-finish") first.finish();
    if (frame === 4 && kind === "replaced-after-snapshot") replacement.finish();
    if (frame === 2 && kind === "animation-during-final-barrier") animations = [replacement];
    if (frame === 5 && kind === "animation-during-final-barrier") replacement.finish();
    const scheduled = frames; frames = [];
    for (const callback of scheduled) {
      callback(frame * 16.67);
      // rAF callbacks can have a microtask checkpoint between them.
      for (let turn = 0; turn < 6; turn++) await Promise.resolve();
    }
    if (frame === 1 && kind === "late-focus") {
      pendingFocus = true;
      frames.push(() => { pendingFocus = false; focusReveals++; });
    }
    const queued = tasks; tasks = [];
    for (const callback of queued) callback();
    for (let turn = 0; turn < 6; turn++) await Promise.resolve();
  }
  let failure = null;
  try {
    assert.equal(resolved, kind !== "finite-keeps-running", "Readiness follows the current active finite set");
    if (resolved) { assert.ok(samples >= 2); assert.ok(channels >= 1); assert.ok(messages >= 1); }
    if (kind === "natural-finish") assert.ok(resolvedAt >= 5, "natural finish still precedes final two-frame barrier");
    if (kind === "replaced-after-snapshot") assert.ok(resolvedAt >= 6, "replacement must finish before final barrier");
    if (kind === "animation-during-final-barrier") assert.ok(resolvedAt >= 7, "new active animation forces another readiness cycle");
    if (["paused-at-entry", "infinite-at-entry"].includes(kind)) assert.equal(finishedReads, 0);
    if (kind === "late-focus") { assert.equal(pendingAtReadiness, false); assert.equal(focusReveals, 1); }
  } catch (error) { failure = error.message; }
  results.push({ kind, status: failure ? "FAIL" : "PASS", failure, resolved, resolvedAt, samples, finishedReads, channels, messages, trace });
}
const bytes = await readFile(new URL("../../../wt-p03/tests/e2e/support/frontend-mission-evidence.ts", import.meta.url));
const report = {
  revision, status: results.every(result => result.status === "PASS") ? "PASS" : "FAIL",
  helperSha256: createHash("sha256").update(bytes).digest("hex"),
  scope: "Exact imported helper in a deterministic Node VM; explicit animation lifecycle and 12 controlled render turns, no DB/browser/network or timeout modification.",
  limitation: "A synthetic counterproof of snapshot/promise dependence, not a reproduction of Chromium's internal F3 transition behavior.",
  results,
};
await writeFile(new URL(`./probe-wait-${revision}.json`, import.meta.url), JSON.stringify(report, null, 2) + "\n");
console.log(JSON.stringify({ revision, status: report.status, helperSha256: report.helperSha256, cases: results.map(({ kind, status, failure }) => ({ kind, status, failure })) }, null, 2));
process.exitCode = report.status === "PASS" ? 0 : 1;
